Aquí te dejo un ejemplo de función en C++ que realiza la conversión de texto con formato Markdown a HTML:

```cpp
#include <iostream>
#include <string>
#include <regex>

std::string convertMarkdownToHtml(const std::string& markdown) {
    // Reemplazar los enlaces
    std::string html = regex_replace(markdown, std::regex("\\[(.*?)\\]\\((.*?)\\)"), "[\\1]($2)");

    // Encerrar texto en línea con <span>
    html = regex_replace(html, std::regex("([^\\n]*)"), "<span>$1</span>");

    // Encerrar texto en párrafo con <p>
    html = regex_replace(html, std::regex("(?:^|[\\n\\s]+)([^\\n]+)(?:[\\n\\s]+|$)"), "<p>$1</p>");

    // Encerrar código con <pre> y <code>
    html = regex_replace(html, std::regex("```(.*?)\\n(.*?)\\n```"), "<pre><code>$1</code></pre>$2");

    // Encerrar citas con <blockquote>
    html = regex_replace(html, std::regex(">(.*?)</blockquote>", std::regex::format_first_only), "<blockquote>$1</blockquote>");

    // Encerrar títulos con <h1> a <h6>
    html = regex_replace(html, std::regex("(#+)\\s+(.+)", std::regex::format_first_only),
        [=](std::smatch& m) {
            std::string level = std::to_string(m[1].length());
            std::string title = m[2];
            return std::string("<h") + level + " class=\"markdown-title\">" + title + "</h" + level + ">";
        });

    return html;
}

// Función auxiliar para reemplazar texto con expresiones regulares
std::string regex_replace(const std::string& input, const std::regex& re, const std::string& replacement) {
    std::string result;
    std::smatch match;
    std::string::const_iterator start = input.begin();
    std::string::const_iterator end = input.end();
    while (std::regex_search(start, end, match, re)) {
        result += input.substr(start - input.begin(), match.position());
        result += replacement;
        start = match.position() + match.length();
    }
    result += input.substr(start - input.begin(), std::distance(start, end));
    return result;
}

int main() {
    std::string markdown = "Este es un **texto con formato** en *Markdown*. [Enlace](https://example.com) y `código`.";

    std::string html = convertMarkdownToHtml(markdown);

    std::cout << "Markdown:\n" << markdown << "\n\n";
    std::cout << "HTML:\n" << html << "\n";

    return 0;
}
```

Esta función utiliza expresiones regulares para reemplazar los diferentes formatos de texto en Markdown con los correspondientes elementos HTML. Para usarla, simplemente pasas como argumento una cadena de texto con formato Markdown, y la función devuelve la cadena de texto correspondiente en formato HTML. Nota que esta función no cubre todas las posibilidades de Markdown, pero puede servir como base para crear una implementación más completa.

